// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed parameters:
    // addrAttacker: the address we will deploy an attacker contract at (fuzzed seed as uint256 converted to address)
    // val: the MinSum value to set
    function testFuzz_property(uint256 seedAddr, uint256 val) public {
        // keep address in valid non-zero range
        address attackerAddr = address(uint160(seedAddr));
        // keep val wide but bounded to avoid weird extremes — still broad
        uint256 newMin = val;

        // Deploy an attacker that will try to re-enter SetMinSum during the call.
        // The reference contract's modifier prevents reentrancy by setting locked_ to true around the call.
        // The mutant removed the state updates, making reentrancy possible.
        ReentrantAttacker attacker = new ReentrantAttacker(c);

        // Fund the attacker so it can perform any payable interactions if needed (not required here)
        vm.deal(address(attacker), 1 ether);

        // The attacker will attempt to call SetMinSum and during that call re-enter SetMinSum again.
        // We call through the attacker so it triggers the reentrancy if the modifier is broken.
        bool ok;
        try attacker.trySetMinSum(newMin) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule (single assertion): On the correct contract, after any call to SetMinSum,
        // MinSum equals the last provided argument of a top-level SetMinSum call (here newMin) and the call should succeed.
        // The reference prevents reentrancy so the attacker's reentrant attempt cannot change MinSum during the same transaction.
        // Therefore we assert that c.MinSum() == newMin. The buggy mutant that allows reentrancy can cause MinSum to differ for some inputs.
        assertTrue(c.MinSum() == newMin);
    }
}

// Minimal adversarial reentrant attacker: it calls c.SetMinSum(...) and in its fallback tries to re-enter SetMinSum again.
contract ReentrantAttacker {
    C public target;
    bool public firstCall = true;
    uint256 public reentrantVal = 0xBEEF;

    constructor(C _t) {
        target = _t;
    }

    // External entry that initiates the attack
    function trySetMinSum(uint256 v) external {
        reentrantVal = v;
        // Call target.SetMinSum via this contract so that if the modifier is broken, target will call into this contract during the call
        // We do a direct call to SetMinSum; if the modifier is broken and target invokes any external call back to us,
        // our fallback will attempt to re-enter SetMinSum with a different value to try to change MinSum.
        target.SetMinSum(v);
    }

    // Fallback that attempts to re-enter SetMinSum once with a different value
    fallback() external payable {
        if (firstCall) {
            firstCall = false;
            // Attempt to re-enter with a different value to cause MinSum to end up different in the buggy mutant
            target.SetMinSum(reentrantVal + 1);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: attacker initial funding and the two different MinSum values
    function testFuzz_property(uint256 fund, uint256 outerVal, uint256 innerVal) public {
        // keep values in reasonable bounds to avoid trivial over/underflows and to ensure funds sufficient
        fund = bound(fund, 1 wei, 1 ether);
        outerVal = bound(outerVal, 0, 1 ether);
        innerVal = bound(innerVal, 0, 1 ether);

        // deploy attacker that will reenter SetMinSum during the SetLogFile or SetMinSum call
        Attacker attacker = new Attacker(address(c), innerVal);

        // fund attacker so it can call and pay gas; attacker will initiate the call
        vm.deal(address(attacker), fund);

        // The attacker will call into c.SetMinSum(outerVal) and during execution reenter
        // by invoking c.SetMinSum(innerVal). On the correct contract the nonReentrant_ modifier
        // prevents the inner call from succeeding, so after the top-level call completes
        // c.MinSum() == outerVal. On the mutant (locking update removed) the reentrant inner
        // call can succeed and leave c.MinSum() == innerVal (!= outerVal) for some inputs.

        // attacker starts the attack
        bool ok;
        try attacker.attack{value: 0}(outerVal) {
            ok = true; // top-level call returned
        } catch {
            ok = false; // should not revert in normal operation
        }

        // Single assertion: after the attack invocation completes, on the correct contract
        // MinSum equals the outerVal the caller requested. The mutant can be reentered and
        // break this property for some inputs (fuzzer should find them).
        assertTrue(ok && c.MinSum() == outerVal);
    }
}

// Minimal attacker that reenters SetMinSum during the outer SetMinSum call.
contract Attacker {
    address target;
    uint256 innerVal;
    bool reentered;

    constructor(address _target, uint256 _innerVal) payable {
        target = _target;
        innerVal = _innerVal;
        reentered = false;
    }

    // This function initiates the first SetMinSum call as msg.sender = this contract
    function attack(uint256 outerVal) external payable {
        // call SetMinSum on target; during modifier execution the attacker will try to reenter
        C(target).SetMinSum(outerVal);
    }

    // Fallback will be invoked if the target contract makes an external call back to this attacker
    // We attempt to reenter SetMinSum once during that call. If reentrancy is prevented by the
    // correct contract, this inner call will revert; we ignore the revert so the outer call proceeds.
    fallback() external payable {
        if (!reentered) {
            reentered = true;
            // attempt reentrant SetMinSum
            // use try/catch to swallow any revert from the protected contract
            try C(target).SetMinSum(innerVal) {
            } catch {
            }
        }
    }
}

