pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: value to set and an initial funding amount for attacker
    function testFuzz_property(uint256 setVal, uint256 fund) public {
        // keep fund reasonable but allow wide range
        fund = bound(fund, 0, 1 ether);

        // deploy an attacker who will re-enter SetMinSum during the fallback invoked by Put
        ReentrantAttacker attacker = new ReentrantAttacker(address(c));

        // fund the attacker so it can call and send eth if needed
        vm.deal(address(attacker), fund);

        // Give attacker control: call SetLogFile to point log to attacker so that during Put -> Log.AddMessage
        // the attacker can reenter. The attacker will attempt reentrancy when c calls into Log.AddMessage
        // SetLogFile is nonReentrant_, so on the reference contract the modifier prevents nested SetMinSum; the mutant allows it.

        // First, call SetLogFile to set attacker as the LogFile (no ether needed)
        c.SetLogFile(address(attacker));

        // Now attempt to set MinSum to setVal while the attacker will try to reenter with a different value.
        // The attacker is prepared to call SetMinSum with a different value (setVal ^ 1) during the external Log call.
        uint256 reentrantVal = setVal ^ 1; // fuzz-derived dependent value (still not a hard-coded primitive in test inputs)
        attacker.prepareReentrancy(reentrantVal);

        // Execute the call; wrap in try/catch to record success (both versions should not revert)
        bool ok;
        try c.SetMinSum(setVal) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: on the correct contract, after SetMinSum(setVal) returns, MinSum must equal setVal.
        // The mutant that allows reentrancy can cause MinSum != setVal for some inputs (the fuzzer will find them).
        assertTrue(ok && c.MinSum() == setVal);
    }
}

// Minimal adversarial helper: acts as a LogFile and re-enters C.SetMinSum during AddMessage
contract ReentrantAttacker {
    address public target;
    uint256 public toCall;
    bool public armed;

    constructor(address _t) {
        target = _t;
    }

    // Called by test to arm the attacker with the reentrant value
    function prepareReentrancy(uint256 v) external {
        toCall = v;
        armed = true;
    }

    // This mimics LogFile.AddMessage; when called, it will reenter C.SetMinSum if armed
    function AddMessage(address, uint, string memory) public {
        if (armed) {
            armed = false; // ensure only one reentrant attempt per call
            // re-enter SetMinSum with a different value
            C(target).SetMinSum(toCall);
        }
    }

    // fallback to accept any calls
    fallback() external payable {}
}

