pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the proposed MinSum value and attacker sent value (as msg.value for reentrant exploit)
    function testFuzz_property(uint256 proposedMin, uint256 attackerFund) public {
        // keep funds reasonable for the test
        attackerFund = bound(attackerFund, 0, 1 ether);

        // deploy a reentrant attacker that will try to call SetMinSum during the first SetMinSum execution
        ReentrantAttacker attacker = new ReentrantAttacker(address(c));

        // fund the attacker so it can send value if needed
        vm.deal(address(attacker), attackerFund);

        // The attacker will be passed as the msg.sender to SetLogFile so that SetMinSum when called
        // will see the attacker as an external party if needed. But SetMinSum itself is public and
        // uses the nonReentrant_ modifier; the malicious behavior is to re-enter SetMinSum from
        // a fallback triggered by a call we cause inside SetMinSum's execution path. To ensure
        // the attacker is able to reenter during the same transaction, we cause the initial
        // SetMinSum call to originate from the attacker.

        // Have the attacker attempt to call SetMinSum(proposedMin). We capture whether the call
        // succeeded. For the correct contract, after the call finishes MinSum must equal proposedMin.
        bool ok;
        try attacker.doSetMin{value: attackerFund}(proposedMin) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: after the external interaction, the contract's MinSum equals the
        // proposedMin when the reference contract enforces non-reentrancy; the mutant will allow
        // reentrancy and for some inputs the final MinSum will differ (test will fail on mutant).
        assertTrue(c.MinSum() == proposedMin);
    }
}

// Minimal reentrant attacker: when it calls SetMinSum on C, its fallback will try to re-enter
// SetMinSum with a different value to try to change MinSum during the outer call.
contract ReentrantAttacker {
    C public target;
    bool public reentered;
    uint256 public innerVal = 0x123;

    constructor(address _t) payable {
        target = C(_t);
    }

    // external helper to start the attack; will call SetMinSum on target as msg.sender
    function doSetMin(uint256 val) external payable {
        innerVal = val ^ 0xDEADBEEF; // choose a different value to attempt to leave MinSum != val
        // call target.SetMinSum as this contract (this will execute modifier and during its execution
        // the fallback may be triggered if target makes an external call back to this contract)
        target.SetMinSum{value: msg.value}(val);
    }

    // fallback: attempt reentrancy into SetMinSum with a different value only once
    fallback() external payable {
        if (!reentered) {
            reentered = true;
            // attempt to re-enter SetMinSum with a different value
            // ignore failures
            try target.SetMinSum(innerVal) {
            } catch {
            }
        }
    }
}

