pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: value to set and an amount of gas to let attacker reenter
    function testFuzz_property(uint256 v, uint256 attackerGas) public {
        // keep attackerGas within reasonable bounds
        attackerGas = bound(attackerGas, 1, 1_000_000);

        // deploy attacker and set it as the Log so attacker can reenter during SetMinSum
        ReentrantAttacker atk = new ReentrantAttacker(address(c));

        // initialize Log to attacker's address so that when SetMinSum is called it will call out
        // Use vm.prank to make the call come from any address (use this contract)
        vm.prank(address(this));
        // pass attacker's address as Log; SetLogFile uses nonReentrant_ so during SetMinSum the modifier will execute
        c.SetLogFile(address(atk));

        // Now call SetMinSum; the attacker is set as Log and its fallback will reenter SetMinSum
        bool ok;
        try c.SetMinSum(v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The invariant for the correct contract: after the call completes, MinSum equals the requested v
        // This will hold for the reference; the mutant (which allows reentrancy) can cause MinSum != v
        assertTrue(ok && c.MinSum() == v);
    }
}

// Attacker contract: when it receives a call (via being set as Log and any later external call), it will
// re-enter SetMinSum with a different value to try to change MinSum during the outer SetMinSum call.
contract ReentrantAttacker {
    address target;
    bool reentered;
    constructor(address _t) {
        target = _t;
        reentered = false;
    }

    // fallback will attempt to reenter once
    fallback() external payable {
        if (!reentered) {
            reentered = true;
            // try to call SetMinSum with a different value
            // use low-level call to avoid revert bubbling
            C(target).SetMinSum(0xDEADBEEF);
        }
    }
}

