pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: caller address and the value to set
    function testFuzz_property(address caller, uint256 val) public {
        // keep caller usable and not zero address
        vm.assume(caller != address(0));
        // deploy adversarial helper that will reenter during SetMinSum if possible
        Attacker attacker = new Attacker(address(c));

        // fund attacker so it can make calls if needed
        vm.deal(address(attacker), 1 ether);

        // Have the fuzzer-supplied caller set the LogFile to attacker so that during SetMinSum
        // any external call path that the mutant exposes (via removed lock) can be exploited by attacker.
        // We must call SetLogFile first; both SetLogFile and SetMinSum are nonReentrant_ protected in reference.
        vm.prank(caller);
        // call SetLogFile with attacker address; if reentrancy removed, attacker may reenter when later external calls occur
        c.SetLogFile(address(attacker));

        // Now have caller call SetMinSum with fuzzed val. In the correct contract this will set MinSum==val.
        bool ok;
        vm.prank(caller);
        try c.SetMinSum(val) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: if the call returned (ok==true) then MinSum equals the provided val.
        // This must hold for the reference for all inputs; the mutant (removed guard) can allow attacker to
        // change state so MinSum != val after return for some inputs — fuzzer should find such case.
        uint256 stored = c.MinSum();
        // single assertion required
        assertTrue(!ok || stored == val);
    }
}

// Minimal adversarial helper: attempts to reenter SetMinSum when used as LogFile or during other external interactions
contract Attacker {
    address public target;
    bool public reentered;
    constructor(address _t) payable {
        target = _t;
        reentered = false;
    }

    // If the target contract makes an external call to this contract (e.g., Log.AddMessage or similar),
    // try to reenter SetMinSum to exploit missing reentrancy guard in mutant.
    fallback() external payable {
        // avoid infinite recursion
        if (!reentered) {
            reentered = true;
            // attempt to call SetMinSum reentrantly with a different value to cause divergence
            (bool s,) = target.call(abi.encodeWithSignature("SetMinSum(uint256)", uint256(123456789)));
            s; // ignore result
        }
    }
}

