pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters: attacker address selector (as uint160) and the value to set
    // We fuzz the attacker identity (so it can be any EOA-like address in the fuzzer space)
    // and the MinSum value. The adversarial behaviour needs a contract, so we deploy
    // an Attacker that will reenter into C during SetMinSum if possible.
    function testFuzz_property(uint160 attackerId, uint256 newMin) public {
        // keep attacker address in normal range (non-zero)
        address attackerAddr = address(uint160(bound(attackerId, 1, type(uint160).max)));

        // Deploy attacker helper from that address so its code originates from that address
        // We use vm.startPrank to make the deployer be the fuzzed attacker address
        vm.startPrank(attackerAddr);
        Attacker attacker = new Attacker(address(c));
        vm.stopPrank();

        // Make sure attacker has some ether to use in potential reentrant flows (not strictly needed here)
        vm.deal(attackerAddr, 1 ether);

        // The general admissible domain: contract must be uninitialized so SetMinSum is allowed.
        // We ensure that by not calling Initialized() or SetMinSum before.

        // Now call SetMinSum via the attacker helper as the caller. The Attacker's fallback/receive
        // will try to reenter C.SetLogFile/SetMinSum/Initialized in order to disturb state only when
        // the nonReentrant_ guard is absent in the mutant. We call SetMinSum on c with newMin
        // from the attacker address (prank) so the helper's call context matches the fuzzed actor.
        vm.prank(attackerAddr);
        // route the call through the attacker so that if mutant allows reentrancy, attacker can exploit
        attacker.callSetMinSum(newMin);

        // Single assertion: on the reference contract, for ANY attacker and ANY newMin, after the call
        // MinSum equals newMin. The mutant (missing guard) can be exploited by Attacker to make it differ.
        assertTrue(c.MinSum() == newMin);
    }
}

// Minimal adversarial helper that tries to reenter C during the external call flow.
// It calls C.SetMinSum from its caller function so that when the test calls attacker.callSetMinSum,
// the attacker will call C.SetMinSum; the attacker also implements a fallback that attempts to
// reenter C by calling SetMinSum again with a different value, if reentrancy is possible.
contract Attacker {
    C target;
    bool first = true;

    constructor(address _target) payable {
        target = C(_target);
    }

    // Called by test to initiate the scenario as the attacker address
    function callSetMinSum(uint256 v) external {
        // Primary call into target; during this call the target may invoke external calls that
        // trigger this contract's fallback/receive. In the mutant (no guard), fallback reentry
        // can change state. Here we simply call target.SetMinSum which is a normal external call.
        target.SetMinSum(v);
    }

    // If during target.SetMinSum any external call ends up invoking this contract (not guaranteed),
    // attempt to reenter and set a different MinSum to disturb state in the mutant.
    fallback() external payable {
        // attempt to reenter only once to avoid infinite recursion
        if (first) {
            first = false;
            // try to change MinSum to a different value (v ^ 0xdead) to make a detectable difference
            // We pick a nonzero arbitrary value; the fuzzer provides the original value so this
            // different value may lead to MinSum != original in the mutant.
            try target.SetMinSum(0xDEADBEEF) {
            } catch {
            }
        }
    }
}

