    // fallback: attempt to reenter SetMinSum once when fallback is hit
    fallback() external payable {
        if (!reentered) {
            reentered = true;
            // try to flip MinSum to a different value by calling SetMinSum with reentryTrigger
            // ignore failures
            try C(target).SetMinSum(reentryTrigger) {
            } catch {
            }
        }
