}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed parameters: the value to set and an arbitrary caller seed
    function testFuzz_property(uint256 v, uint256 callerSeed) public {
        // keep caller address in wide domain but non-zero
        address attackerAddr = address(uint160(bound(uint160(callerSeed), 1, type(uint160).max)));

        // deploy a reentrant helper that will attempt to reenter SetMinSum during the call
        ReentrantAttacker attacker = new ReentrantAttacker(c);

        // fund the attacker so it can make calls if needed (not strictly necessary here)
        vm.deal(address(attacker), 1 ether);

        // The adversarial behavior: Set the attacker's address as the Log contract so that when
        // SetMinSum is called it will trigger the attacker via an external call path.
        // However the reference contract's nonReentrant_ prevents reentrancy; the mutant removes it.

        // First, ensure contract is not yet initialized (default false) and set the Log to attacker
        // We call SetLogFile with the attacker's address. This call must succeed beforehand.
        // msg.sender is this test contract by default.
        c.SetLogFile(address(attacker));

        // Now arrange for the attacker to reenter during SetMinSum by having attacker configured to
        // call back to c.SetMinSum with a different value when it receives a callback from c.
        attacker.configureReentry(v + 1);

        // Now perform the call that should set MinSum to v. We call from the attacker address to
        // emulate an adversarial caller (prank to set msg.sender). The attacker will try to reenter.
        vm.prank(attackerAddr);

        // We cannot cause the test fuzzer to control the code at attackerAddr (it's just an EOA),
        // so instead we have the deployed attacker contract be the Log contract and we call SetMinSum
        // from this test (prank to attackerAddr) to set msg.sender to an address different from the
        // deployed attacker; this still allows the deployed attacker to be invoked by c via Log.AddMessage
        // because c.Log points to the deployed attacker contract.

        // Capture whether SetMinSum call returns (no revert). Use try/catch to satisfy rules.
        bool ok;
        try c.SetMinSum(v) { ok = true; } catch { ok = false; }

        // The universal property we assert: after SetMinSum(v) returns (successful or not), the
        // reference contract always stores MinSum == v when the call succeeds. The mutant can be
        // exploited by the reentrant attacker so that after the call returns MinSum != v for some inputs.
        // We make a single assertion reading c.MinSum(). Note: if the call reverted, ok==false and the
        // reference contract wouldn't have set MinSum; but SetMinSum on the reference does not revert
        // when not initialized, so ok should be true and MinSum must equal v.

        // Assert the invariant: if SetMinSum returned (ok==true) then MinSum equals v. This reads c.MinSum().
        // We encode this as a single assertTrue as required: ok implies equality. For simplicity, assert
        // that either the call reverted (ok==false) OR MinSum == v. However on the reference implementation
        // call should not revert and MinSum == v holds for all inputs; the mutant allows a reentrant change
        // so the assertion will fail for some inputs against the mutant.
        assertTrue(!ok || c.MinSum() == v);
    }
}

// Minimal reentrant adversary: when its AddMessage is called by C (as Log), it will call back
// into C.SetMinSum with a different value to attempt to disturb state during execution.
contract ReentrantAttacker {
    C public target;
    uint256 public reentryValue;

    constructor(C _t) {
        target = _t;
    }

    function configureReentry(uint256 v) external {
        reentryValue = v;
    }

    // This matches the LogFile.AddMessage signature used by C; it's public so C can call it.
    function AddMessage(address, uint, string memory) public {
        // attempt to reenter SetMinSum on the target during its execution
