        // call Put with lock time 0, sending value
        c.Put{value: value}(0);

        // The invariant: after Put by an address starting from zero, the stored balance for that address
        // (accessible via the public mapping getter Acc) is at least the sent value.
        // This holds in the reference (which adds msg.value to acc.balance) and is broken by the mutant
        // that omits updating acc.balance.
        (, uint256 storedBalance) = viewAcc(actor);
        assertTrue(storedBalance >= value);
    }

    // helper to read the Holder struct returned by the public mapping getter
    function viewAcc(address a) internal returns (address, uint256) {
        // The public mapping Acc creates a getter with signature: function Acc(address) public view returns (uint unlockTime, uint balance);
        // We call it via low-level staticcall to avoid Solidity expecting specific tuple names here — but direct call is fine too.
        return c.Acc(a);
    }
}

